// Generated by scaffold-html-to-react-page (deterministic design transpile) from html/frontend/12-exam.html
// Structure + styling are faithful to the proto. DATA WIRING (fetch/list/handlers) is layered on after.
import { useMemo, useState } from 'react';
import { useNavigate, useParams } from 'react-router';
import { ArrowLeft, CheckCircle2, ChevronLeft, ChevronRight, Circle, Flag, Info, Timer } from 'lucide-react';
import { useScreenQuery } from '~/hooks/useScreenQuery';
import { useAppSelector } from '~/hooks/useAppSelector';
import '~/styles/protos/exam.css';

const TOTAL_QUESTIONS = 50;
const OPTIONS = ['৫', '৪', '৬', '১০'] as const;
const BN_DIGITS = ['০', '১', '২', '৩', '৪', '৫', '৬', '৭', '৮', '৯'];

function bn(value: number): string {
  return String(value)
    .split('')
    .map((d) => BN_DIGITS[Number(d)] ?? d)
    .join('');
}

export default function ExamPage() {
  const sessionUser = useAppSelector((s) => s.auth.user);
  const { data } = useScreenQuery("GET /api/exams/:id");
  const { examId } = useParams();
  const navigate = useNavigate();

  // The paper is rendered from the design fixture; answers and position are
  // tracked locally until GET /api/exams/:id feeds real questions into the view.
  const [current, setCurrent] = useState(2);
  const [answers, setAnswers] = useState<Record<number, number>>({ 1: 0, 2: 1 });
  const [flagged, setFlagged] = useState<number[]>([2]);
  const [confirming, setConfirming] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  const answeredCount = useMemo(() => Object.keys(answers).length, [answers]);
  const unanswered = TOTAL_QUESTIONS - answeredCount;
  const selected = answers[current];
  const isFlagged = flagged.includes(current);

  const goTo = (index: number) => {
    setCurrent(Math.min(TOTAL_QUESTIONS, Math.max(1, index)));
    setConfirming(false);
  };

  const toggleFlag = () => {
    setFlagged((prev) => (prev.includes(current) ? prev.filter((n) => n !== current) : [...prev, current]));
  };

  const choose = (optionIndex: number) => {
    if (submitting) return;
    setAnswers((prev) => ({ ...prev, [current]: optionIndex }));
  };

  const submit = () => {
    if (!confirming) {
      if (unanswered > 0) {
        setConfirming(true);
        return;
      }
      setConfirming(true);
      return;
    }
    setSubmitting(true);
    navigate(`/exams/${examId ?? ''}/result`);
  };

  const chipClass = (index: number) => {
    const classes = ['ksr-chip'];
    if (answers[index] !== undefined) classes.push('is-on');
    if (flagged.includes(index)) classes.push('is-flag');
    return classes.join(' ');
  };

  return (
    <div data-testid="exam-page">
      <span className="sr-only" data-testid="screen-data-status">{data ? 'synced' : 'loading'}<span className="sr-only" data-testid="session-user">{sessionUser?.email ?? ''}</span></span>
      <header className="ksr-appbar" >
          <a className="ksr-back" href="/exams" aria-label="ফিরে যান" data-testid="sub-back">
            <ArrowLeft  />
            ফিরে যান
          </a>
          <span className="ksr-appbar-title" data-slot="title" data-testid="sub-title">পরীক্ষা</span>
        </header>
      
        <main className="ksr-main sf-exam" >
      
          
          <div className="row">
            <p className="t-caption ksr-grow" data-testid="exam-counter">প্রশ্ন {bn(current)} / {bn(TOTAL_QUESTIONS)}</p>
            <span className="ksr-badge" role="timer" data-testid="exam-timer">
              <Timer  />
              ৫৭:৩২
            </span>
            <span className="ksr-badge is-ok" data-testid="exam-saved">
              <CheckCircle2  />
              সংরক্ষিত হয়েছে
            </span>
          </div>
      
          
          <div className="progress is-sm" role="progressbar" aria-valuenow={current * 2} aria-valuemin={0} aria-valuemax={100} aria-label="পরীক্ষার অগ্রগতি">
            <div className="progress-fill" style={{ width: `${(current / TOTAL_QUESTIONS) * 100}%` }} data-testid="exam-bar"></div>
          </div>
      
          
          <div className="ex-nav" role="group" aria-label="প্রশ্ন নেভিগেশন">
            <button className={chipClass(1)} type="button" aria-pressed={answers[1] !== undefined} onClick={() => goTo(1)} data-testid="exam-nav-q1">১</button>
            <button className={chipClass(2)} type="button" aria-pressed={answers[2] !== undefined} onClick={() => goTo(2)} data-testid="exam-nav-q2">
              {flagged.includes(2) ? <Flag  /> : null}
              ২
            </button>
            <button className={chipClass(3)} type="button" aria-pressed={answers[3] !== undefined} onClick={() => goTo(3)} data-testid="exam-nav-q3">৩</button>
            <button className={chipClass(4)} type="button" aria-pressed={answers[4] !== undefined} onClick={() => goTo(4)} data-testid="exam-nav-q4">৪</button>
            <button className={chipClass(5)} type="button" aria-pressed={answers[5] !== undefined} onClick={() => goTo(5)} data-testid="exam-nav-q5">৫</button>
            <button className="ksr-chip" type="button" onClick={() => goTo(TOTAL_QUESTIONS)} data-testid="exam-nav-more">+{bn(TOTAL_QUESTIONS - 5)}</button>
          </div>
      
          
          <section className="ksr-section" aria-labelledby="exam-question">
            <div className="row">
              <span className="ksr-badge" data-testid="exam-subject">গণিত</span>
              <span className="t-caption" data-testid="exam-qtype">বহুনির্বাচনী</span>
            </div>
            <h1 className="t-display-md" id="exam-question" data-testid="exam-question">
              ২৫ এর ২০% কত?
            </h1>
          </section>
      
          
          <div className="ex-opts" role="group" aria-label="উত্তরের বিকল্প">
            {OPTIONS.map((value, index) => {
              const isSelected = selected === index;
              return (
                <button
                  key={value}
                  className="ex-opt"
                  type="button"
                  aria-pressed={isSelected}
                  onClick={() => choose(index)}
                  data-testid="exam-option"
                  data-id={index === 1 ? 'q2-b' : undefined}
                >
                  {isSelected ? <CheckCircle2  /> : <Circle  />}
                  {value}
                </button>
              );
            })}
          </div>
      
          
          <section className="ksr-panel" data-component="card" data-testid="exam-note">
            <div className="row" style={{ alignItems: 'flex-start' }}>
              <Info  />
              <p className="t-caption ksr-grow" data-testid="exam-note-text">
                উত্তর নির্বাচন করলে নিজে থেকে সংরক্ষণ হবে। পরে ফিরে এসে বদলাতে পারবে।
              </p>
            </div>
          </section>
      
          
          <div className="ksr-stack">
            <div className="ex-foot">
              <button className="ksr-btn is-quiet" style={{ flex: '1' }} type="button" disabled={current === 1} onClick={() => goTo(current - 1)} data-testid="exam-prev">
                <ChevronLeft  />
                আগের
              </button>
              <button className="ksr-btn" style={{ flex: '1' }} type="button" disabled={current === TOTAL_QUESTIONS} onClick={() => goTo(current + 1)} data-testid="exam-next">
                পরের প্রশ্ন
                <ChevronRight  />
              </button>
            </div>
            <button className="ksr-btn is-quiet is-block" type="button" aria-pressed={isFlagged} onClick={toggleFlag} data-testid="exam-flag">
              <Flag  />
              ফ্ল্যাগ
            </button>

            {confirming ? (
              <section className="ksr-panel" data-component="card" role="alertdialog" aria-labelledby="exam-confirm-title" data-testid="exam-confirm">
                <p className="t-body-sm t-semibold" id="exam-confirm-title" data-testid="exam-confirm-title">
                  {unanswered > 0 ? `${bn(unanswered)} টি প্রশ্ন এখনো বাকি আছে। তবু জমা দেবে?` : 'সব প্রশ্নের উত্তর দেওয়া হয়েছে। জমা দেবে?'}
                </p>
                <div className="row" style={{ marginTop: 'var(--space-md)' }}>
                  <button className="ksr-btn is-quiet ksr-grow" type="button" onClick={() => setConfirming(false)} data-testid="exam-confirm-back">
                    ফিরে যাও
                  </button>
                  <button className="ksr-btn ksr-grow" type="button" disabled={submitting} onClick={submit} data-testid="exam-confirm-yes">
                    হ্যাঁ, জমা দাও
                  </button>
                </div>
              </section>
            ) : (
              <button className="ksr-btn is-block" type="button" disabled={submitting} onClick={submit} data-testid="exam-submit">জমা দাও</button>
            )}
          </div>
      
        </main>
    </div>
  );
}
